import { connect, JSONCodec } from 'nats';
export async function listenOrderEmails() {
  const nc = await connect({ servers: process.env.NATS_URL || 'nats://nats:4222' });
  const jc = JSONCodec();
  const sub = nc.subscribe('events.orders.completed');
  for await (const m of sub) { const order = jc.decode(m.data); console.log('Dispatching email for order:', order.id); }
}
